package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class InvestActivity extends FinseqActivity{
 LinearLayout root,body,summary,market;
 @Override public void onCreate(Bundle b){super.onCreate(b);render();load();}
 @Override protected void onResume(){super.onResume();if(summary!=null)load();}
 void render(){root=Ui.column(this);Ui.appHeader(root,this,"Mutual Funds · NSE Invest");body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.text(this,"Mutual Fund Dashboard",25,true));body.addView(Ui.sub(this,"Client 360 · onboarding · orders · SIP/XSIP activity"));summary=Ui.card(this);summary.addView(Ui.sub(this,"Loading NSE Invest dashboard…"));body.addView(summary);
  Button ucc=Ui.greenButton(this,"Create UCC / Onboarding");Button clients=Ui.button(this,"Clients / MF Investors");Button profiles=Ui.button(this,"NSE Profiles");Button orders=Ui.button(this,"Orders / SIP Activity");Button mandates=Ui.button(this,"NSE Mandates · Bulk Sync");body.addView(ucc);body.addView(clients);body.addView(profiles);body.addView(orders);body.addView(mandates);
  ucc.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(InvestActivity.this,UccOnboardingActivity.class));}});
  clients.setOnClickListener(new View.OnClickListener(){public void onClick(View v){openList("investors");}});
  profiles.setOnClickListener(new View.OnClickListener(){public void onClick(View v){openList("profiles");}});
  orders.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(InvestActivity.this,OrdersActivity.class));}});
  mandates.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(InvestActivity.this,MandatesActivity.class));}});
  body.addView(Ui.text(this,"NSE Scheme Master",19,true));market=new LinearLayout(this);market.setOrientation(LinearLayout.VERTICAL);body.addView(market);addMarket("SCH","Search all schemes","Search the live production scheme master","");addMarket("SC","Small Cap","Explore available small-cap schemes","Small Cap");addMarket("MC","Mid Cap","Explore available mid-cap schemes","Mid Cap");addMarket("LC","Large Cap","Explore available large-cap schemes","Large Cap");addMarket("TS","Tax Saving","Explore available ELSS schemes","ELSS");Ui.setScreen(this,root,2);
 }
 void addMarket(String icon,String title,String sub,final String query){LinearLayout row=Ui.actionRow(this,icon,title,sub);row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(InvestActivity.this,SchemesActivity.class).putExtra("search",query));}});market.addView(row);}
 void load(){Ui.run(this,new Runnable(){public void run(){try{final JSONObject result=ApiClient.get(InvestActivity.this,"/api/v2/mf/dashboard");Ui.ui(InvestActivity.this,new Runnable(){public void run(){show(result);}});}catch(final Exception error){Ui.ui(InvestActivity.this,new Runnable(){public void run(){Ui.toast(InvestActivity.this,error.getMessage());}});}}});}
 void show(JSONObject j){summary.removeAllViews();JSONObject s=j.optJSONObject("summary");if(s==null)s=new JSONObject();summary.addView(Ui.text(this,"Finseq Financial Services",18,true));summary.addView(Ui.sub(this,"Live NSE Invest operations dashboard"));LinearLayout r1=new LinearLayout(this);r1.setOrientation(LinearLayout.HORIZONTAL);r1.addView(Ui.text(this,"Investors\n"+s.optInt("investors"),17,true),new LinearLayout.LayoutParams(0,-2,1));r1.addView(Ui.text(this,"NSE Profiles\n"+s.optInt("nse_profiles"),17,true),new LinearLayout.LayoutParams(0,-2,1));summary.addView(r1);LinearLayout r2=new LinearLayout(this);r2.setOrientation(LinearLayout.HORIZONTAL);r2.addView(Ui.text(this,"Orders\n"+s.optInt("orders"),16,true),new LinearLayout.LayoutParams(0,-2,1));r2.addView(Ui.text(this,"SIP / XSIP\n"+s.optInt("sip"),16,true),new LinearLayout.LayoutParams(0,-2,1));summary.addView(r2);summary.addView(Ui.text(this,"Next UCC: "+j.optString("next_ucc","—"),17,true));summary.addView(Ui.sub(this,"Centralized sequence · manual UCC entry disabled"));}
 void openList(String mode){startActivity(new Intent(this,MfListActivity.class).putExtra("mode",mode));}
}
